// apps/agents/voice/events.ts
import { z } from "iterate/sdk";
var Activation = z.string().min(1).max(64);
var Transcript = z.array(
  z.object({ role: z.enum(["listener", "assistant"]), text: z.string() })
);
var DelegationRequestedPayload = z.looseObject({
  activation: Activation,
  conversationId: z.string(),
  delegationId: z.string(),
  transcript: Transcript
});
var thinkingEvent = {
  description: "A backend note for the live model to use quietly.",
  payloadSchema: z.object({
